}

// The client list: a row per client with controls to open its detail or archive it.
function ClientsTable({
  clients,
  onOpen,
  onEdit,
  onArchive,
}: {
  clients: Client[];
  onOpen: (id: number) => void;
  onEdit: (id: number) => void;
  onArchive: (id: number) => void;
}) {
  return (
    <table data-testid="clients-table">
